import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { 
    Calendar, Check, X, Plus, RefreshCw, 
    Save, FileText, Clock, MessageSquare,
    Eye, Target, Users
} from 'lucide-react';
import axios from 'axios';
import toast from 'react-hot-toast';

const DailyTracker = () => {
    const { user, token } = useAuth();
    const [tasks, setTasks] = useState([]);
    const [selectedDay, setSelectedDay] = useState(null);
    const [loading, setLoading] = useState(true);
    const [creating, setCreating] = useState(false);
    const [selectedTask, setSelectedTask] = useState(null);
    const [taskNote, setTaskNote] = useState('');
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [showHistory, setShowHistory] = useState(false);
    
    const today = new Date();
    const currentMonth = today.getMonth();
    const currentYear = today.getFullYear();
    const currentDay = today.getDate();
    
    const targetDate = new Date(2026, 10, 30);
    const daysRemaining = Math.ceil((targetDate - today) / (1000 * 60 * 60 * 24));
    
    const getDaysInMonth = (month, year) => {
        return new Date(year, month + 1, 0).getDate();
    };
    
    const daysInMonth = getDaysInMonth(currentMonth, currentYear);
    const monthNames = ['January', 'February', 'March', 'April', 'May', 'June', 
                        'July', 'August', 'September', 'October', 'November', 'December'];

    useEffect(() => {
        if (user) {
            console.log('User loaded:', user);
            fetchTasks();
        } else {
            console.log('No user found!');
        }
    }, [user]);

    const fetchTasks = async () => {
        try {
            console.log('Fetching tasks for user:', user.id);
            const response = await axios.get(
                `http://localhost:8081/api/tasks/user/${user.id}`,
                { headers: { Authorization: `Bearer ${token}` } }
            );
            console.log('Tasks fetched:', response.data);
            setTasks(response.data);
            setLoading(false);
        } catch (error) {
            console.error('Failed to fetch tasks:', error);
            toast.error('Failed to load tasks');
            setLoading(false);
        }
    };

    const createTaskForDay = async (day) => {
        setCreating(true);
        try {
            const date = new Date(currentYear, currentMonth, day);
            const dateStr = date.toISOString().split('T')[0];
            
            console.log('Creating task for day:', day, 'date:', dateStr);
            console.log('User ID:', user.id);
            
            const response = await axios.post(
                `http://localhost:8081/api/tasks/user/${user.id}/day/${day}?date=${dateStr}`,
                {},
                { 
                    headers: { 
                        'Authorization': `Bearer ${token}`,
                        'Content-Type': 'application/json'
                    } 
                }
            );
            console.log('Task created:', response.data);
            setTasks([...tasks, response.data]);
            toast.success(`Tasks created for ${monthNames[currentMonth]} ${day}`);
            return response.data;
        } catch (error) {
            console.error('Failed to create task:', error);
            if (error.response) {
                toast.error(`Error ${error.response.status}: ${error.response.data?.message || 'Failed to create tasks'}`);
            } else if (error.request) {
                toast.error('Backend not responding! Make sure backend is running on port 8081');
            } else {
                toast.error('Failed to create tasks: ' + error.message);
            }
            return null;
        } finally {
            setCreating(false);
        }
    };

    const toggleTask = async (taskId, field) => {
        const task = tasks.find(t => t.id === taskId);
        if (!task) return;

        const updatedTask = { ...task, [field]: !task[field] };
        
        try {
            const response = await axios.put(
                `http://localhost:8081/api/tasks/${taskId}`,
                updatedTask,
                { headers: { Authorization: `Bearer ${token}` } }
            );
            setTasks(tasks.map(t => t.id === taskId ? response.data : t));
            toast.success('Task updated ✅');
        } catch (error) {
            console.error('Failed to update task:', error);
            toast.error('Failed to update task');
        }
    };

    const updateTaskNote = async (taskId, note) => {
        const task = tasks.find(t => t.id === taskId);
        if (!task) return;

        const updatedTask = { ...task, notes: note };
        
        try {
            const response = await axios.put(
                `http://localhost:8081/api/tasks/${taskId}`,
                updatedTask,
                { headers: { Authorization: `Bearer ${token}` } }
            );
            setTasks(tasks.map(t => t.id === taskId ? response.data : t));
            toast.success('Note saved! 💾');
        } catch (error) {
            console.error('Failed to save note:', error);
            toast.error('Failed to save note');
        }
    };

    const handleDayClick = async (day) => {
        console.log('Day clicked:', day);
        setSelectedDay(day);
        const dayTasks = tasks.filter(task => task.day === day);
        console.log('Existing tasks for day:', dayTasks);
        if (dayTasks.length === 0 && !creating) {
            await createTaskForDay(day);
        }
    };

    const handleTaskClick = (task, field) => {
        const labels = {
            javaCompleted: 'Java',
            leetcodeCompleted: 'LeetCode',
            dsaCompleted: 'DSA/OOP',
            sqlCompleted: 'SQL/APIs',
            projectCompleted: 'Project',
            githubCompleted: 'GitHub/Portfolio'
        };
        setSelectedTask({ task, field, label: labels[field] });
        setTaskNote(task.notes || '');
        setIsModalOpen(true);
    };

    const saveNote = () => {
        if (selectedTask) {
            updateTaskNote(selectedTask.task.id, taskNote);
            setIsModalOpen(false);
        }
    };

    const getDayTasks = (day) => tasks.filter(task => task.day === day);

    const getDayStatus = (day) => {
        const dayTasks = getDayTasks(day);
        if (dayTasks.length === 0) return 'empty';
        const completed = dayTasks.filter(t => t.overallCompleted).length;
        if (completed === dayTasks.length) return 'done';
        if (completed > 0) return 'partial';
        return 'started';
    };

    const tasksWithNotes = tasks.filter(t => t.notes && t.notes.trim() !== '');
    const totalCompleted = tasks.filter(t => t.overallCompleted).length;
    const totalTasks = tasks.length;
    const progressPercent = totalTasks > 0 ? Math.round((totalCompleted / totalTasks) * 100) : 0;

    if (loading) {
        return (
            <div className="flex items-center justify-center h-64">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
            </div>
        );
    }

    const taskLabels = [
        { key: 'javaCompleted', label: '☕ Java (1.5h)', icon: '📚' },
        { key: 'leetcodeCompleted', label: '💻 LeetCode (1+)', icon: '🎯' },
        { key: 'dsaCompleted', label: '📊 DSA/OOP (1h)', icon: '🧩' },
        { key: 'sqlCompleted', label: '🗄️ SQL/APIs (1h)', icon: '🔗' },
        { key: 'projectCompleted', label: '🚀 Project (2-3h)', icon: '⚡' },
        { key: 'githubCompleted', label: '📁 GitHub/Portfolio', icon: '📝' }
    ];

    const calendarDays = [];
    for (let day = 1; day <= daysInMonth; day++) {
        calendarDays.push(day);
    }

    const weekDays = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

    return (
        <div className="max-w-7xl mx-auto">
            {/* Modal */}
            {isModalOpen && selectedTask && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50">
                    <div className="bg-white rounded-2xl max-w-md w-full p-6 shadow-2xl">
                        <div className="flex items-center justify-between mb-4">
                            <div>
                                <h3 className="text-xl font-bold text-gray-800">
                                    {selectedTask.label} - {monthNames[currentMonth]} {selectedTask.task.day}
                                </h3>
                                <p className="text-sm text-gray-500">📝 Add your learning notes</p>
                            </div>
                            <button 
                                onClick={() => setIsModalOpen(false)}
                                className="p-2 hover:bg-gray-100 rounded-lg"
                            >
                                <X size={20} />
                            </button>
                        </div>
                        
                        <div className="mb-4">
                            <div className="flex items-center gap-2 text-sm text-gray-500 mb-2">
                                <MessageSquare size={16} />
                                <span>What did you learn today?</span>
                            </div>
                            <textarea
                                value={taskNote}
                                onChange={(e) => setTaskNote(e.target.value)}
                                placeholder="📝 Write what you studied, concepts learned, problems solved..."
                                className="w-full p-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-transparent resize-none h-40"
                            />
                            <div className="flex items-center gap-2 mt-2 text-xs text-gray-400">
                                <Clock size={12} />
                                <span>Tip: Include topics, code snippets, or resources</span>
                            </div>
                        </div>
                        
                        <div className="flex gap-3">
                            <button
                                onClick={saveNote}
                                className="flex-1 bg-blue-600 text-white px-4 py-2 rounded-xl hover:bg-blue-700 transition flex items-center justify-center gap-2"
                            >
                                <Save size={18} />
                                Save Note 💾
                            </button>
                            <button
                                onClick={() => setIsModalOpen(false)}
                                className="px-4 py-2 border border-gray-200 rounded-xl hover:bg-gray-50 transition"
                            >
                                Cancel
                            </button>
                        </div>
                    </div>
                </div>
            )}

            <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6">
                {/* Header */}
                <div className="flex flex-wrap items-center justify-between mb-6 gap-4">
                    <div className="flex items-center gap-3">
                        <Calendar size={28} className="text-blue-600" />
                        <div>
                            <h1 className="text-2xl font-bold text-gray-800">
                                📅 {monthNames[currentMonth]} {currentYear}
                            </h1>
                            <div className="flex items-center gap-3 text-sm text-gray-500">
                                <span>Today: {currentDay} {monthNames[currentMonth]}</span>
                                <span className="w-1 h-1 bg-gray-300 rounded-full"></span>
                                <span className="flex items-center gap-1 text-orange-600">
                                    <Target size={14} />
                                    {daysRemaining} days until target
                                </span>
                            </div>
                        </div>
                    </div>
                    <div className="flex items-center gap-3 flex-wrap">
                        <div className="bg-blue-50 px-3 py-1.5 rounded-full text-sm text-blue-600 flex items-center gap-1">
                            <Users size={16} />
                            {tasksWithNotes.length} notes
                        </div>
                        <div className="bg-green-50 px-3 py-1.5 rounded-full text-sm text-green-600 flex items-center gap-1">
                            <Check size={16} />
                            {progressPercent}% done
                        </div>
                        <button 
                            onClick={fetchTasks}
                            className="flex items-center gap-2 text-sm text-gray-500 hover:text-gray-700"
                        >
                            <RefreshCw size={16} />
                            Refresh
                        </button>
                    </div>
                </div>

                {/* Progress Bar */}
                <div className="mb-6 bg-gray-100 rounded-full h-2.5">
                    <div 
                        className="bg-gradient-to-r from-blue-500 to-purple-500 h-2.5 rounded-full transition-all duration-500"
                        style={{ width: `${progressPercent}%` }}
                    />
                </div>

                {/* Notes History */}
                {showHistory && tasksWithNotes.length > 0 && (
                    <div className="mb-6 bg-purple-50 rounded-xl p-4 border border-purple-200">
                        <div className="flex items-center justify-between mb-3">
                            <h4 className="font-semibold text-purple-800 flex items-center gap-2">
                                <MessageSquare size={18} />
                                Communication Notes ({tasksWithNotes.length})
                            </h4>
                            <button 
                                onClick={() => setShowHistory(false)}
                                className="text-sm text-purple-600 hover:text-purple-800"
                            >
                                Close ✕
                            </button>
                        </div>
                        <div className="space-y-2 max-h-60 overflow-y-auto">
                            {tasksWithNotes.map((task) => (
                                <div key={task.id} className="bg-white rounded-lg p-3 border border-purple-100">
                                    <div className="flex items-center justify-between">
                                        <span className="text-sm font-medium text-gray-700">
                                            📅 {monthNames[currentMonth]} {task.day} - {taskLabels.find(t => task[t.key])?.label || 'Task'}
                                        </span>
                                        <span className="text-xs text-gray-400">
                                            {task.updatedAt ? new Date(task.updatedAt).toLocaleDateString() : 'Today'}
                                        </span>
                                    </div>
                                    <p className="text-sm text-gray-600 mt-1">{task.notes}</p>
                                </div>
                            ))}
                        </div>
                    </div>
                )}

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                    {/* Calendar */}
                    <div className="lg:col-span-2">
                        <div className="grid grid-cols-7 gap-1.5">
                            {weekDays.map(day => (
                                <div key={day} className="text-center text-xs font-medium text-gray-500 py-1">
                                    {day}
                                </div>
                            ))}
                            {calendarDays.map((day) => {
                                const status = getDayStatus(day);
                                let bgColor = 'bg-gray-50 hover:bg-gray-100';
                                let textColor = 'text-gray-600';
                                let ring = '';
                                
                                if (day === currentDay && currentMonth === new Date().getMonth()) {
                                    ring = 'ring-2 ring-red-500 ring-offset-2';
                                }
                                
                                if (status === 'done') {
                                    bgColor = 'bg-green-500 hover:bg-green-600';
                                    textColor = 'text-white';
                                } else if (status === 'partial') {
                                    bgColor = 'bg-yellow-400 hover:bg-yellow-500';
                                    textColor = 'text-white';
                                } else if (status === 'started') {
                                    bgColor = 'bg-blue-200 hover:bg-blue-300';
                                    textColor = 'text-gray-700';
                                }
                                
                                const isSelected = selectedDay === day;
                                
                                return (
                                    <button
                                        key={day}
                                        onClick={() => handleDayClick(day)}
                                        className={`aspect-square rounded-lg flex items-center justify-center text-sm font-medium transition-all ${bgColor} ${textColor} ${isSelected ? 'ring-2 ring-blue-500 ring-offset-2' : ''} ${ring}`}
                                    >
                                        {day}
                                    </button>
                                );
                            })}
                        </div>

                        <div className="flex flex-wrap items-center gap-4 mt-4 text-xs text-gray-500">
                            <div className="flex items-center gap-1.5">
                                <div className="w-3 h-3 bg-green-500 rounded"></div>
                                <span>✅ Done</span>
                            </div>
                            <div className="flex items-center gap-1.5">
                                <div className="w-3 h-3 bg-yellow-400 rounded"></div>
                                <span>🟡 Partial</span>
                            </div>
                            <div className="flex items-center gap-1.5">
                                <div className="w-3 h-3 bg-blue-200 rounded"></div>
                                <span>🔵 Started</span>
                            </div>
                            <div className="flex items-center gap-1.5">
                                <div className="w-3 h-3 bg-gray-50 border border-gray-200 rounded"></div>
                                <span>⬜ Empty</span>
                            </div>
                            <div className="flex items-center gap-1.5">
                                <div className="w-3 h-3 ring-2 ring-red-500 ring-offset-1 bg-gray-50 rounded"></div>
                                <span>🔴 Today</span>
                            </div>
                        </div>
                    </div>

                    {/* Task List */}
                    <div className="bg-gray-50 rounded-xl p-4">
                        <h3 className="font-semibold text-gray-800 mb-3 flex items-center gap-2">
                            <FileText size={18} className="text-blue-600" />
                            {selectedDay ? `Day ${selectedDay} Tasks` : 'Select a day'}
                        </h3>
                        
                        {selectedDay ? (
                            <div className="space-y-2">
                                {taskLabels.map(({ key, label, icon }) => {
                                    const dayTasks = getDayTasks(selectedDay);
                                    const task = dayTasks[0];
                                    const isCompleted = task ? task[key] : false;
                                    const hasNote = task?.notes && task.notes.trim() !== '';
                                    
                                    return (
                                        <div
                                            key={key}
                                            onClick={() => task && handleTaskClick(task, key)}
                                            className={`flex items-center justify-between p-3 bg-white rounded-lg cursor-pointer transition-all hover:shadow-md ${
                                                isCompleted ? 'border-l-4 border-green-500' : 'border-l-4 border-gray-300'
                                            }`}
                                        >
                                            <div className="flex items-center gap-2 flex-1 min-w-0">
                                                <span className="text-base flex-shrink-0">{icon}</span>
                                                <span className={`text-sm truncate ${isCompleted ? 'text-gray-400 line-through' : 'text-gray-700'}`}>
                                                    {label}
                                                </span>
                                                {hasNote && (
                                                    <span className="text-xs text-blue-500 bg-blue-50 px-1.5 py-0.5 rounded-full flex-shrink-0 flex items-center gap-1">
                                                        <MessageSquare size={10} />
                                                        note
                                                    </span>
                                                )}
                                            </div>
                                            <button
                                                onClick={(e) => {
                                                    e.stopPropagation();
                                                    if (task) toggleTask(task.id, key);
                                                }}
                                                className={`w-6 h-6 rounded-full flex items-center justify-center flex-shrink-0 ${
                                                    isCompleted ? 'bg-green-500 text-white' : 'bg-gray-200 text-gray-500'
                                                }`}
                                            >
                                                {isCompleted ? <Check size={14} /> : <X size={14} />}
                                            </button>
                                        </div>
                                    );
                                })}
                                
                                {getDayTasks(selectedDay).length === 0 && !creating && (
                                    <div className="text-center py-8">
                                        <p className="text-gray-500 text-sm mb-3">No tasks for this day</p>
                                        <button
                                            onClick={() => handleDayClick(selectedDay)}
                                            className="bg-blue-600 text-white px-4 py-2 rounded-lg text-sm hover:bg-blue-700 transition flex items-center gap-2 mx-auto"
                                        >
                                            <Plus size={16} />
                                            Create Tasks
                                        </button>
                                    </div>
                                )}
                                
                                {creating && (
                                    <div className="text-center py-8">
                                        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600 mx-auto"></div>
                                        <p className="text-gray-500 text-sm mt-2">Creating tasks...</p>
                                    </div>
                                )}
                            </div>
                        ) : (
                            <div className="flex items-center justify-center h-48 text-gray-400 text-sm">
                                Click a day on the calendar
                            </div>
                        )}
                    </div>
                </div>
                
                {/* Footer */}
                <div className="mt-6 pt-4 border-t border-gray-100 flex flex-wrap items-center justify-between gap-2">
                    <div className="flex items-center gap-2 text-xs text-gray-400">
                        <MessageSquare size={14} className="text-blue-500" />
                        <span>Click any task to add communication notes</span>
                    </div>
                    {tasksWithNotes.length > 0 && (
                        <button
                            onClick={() => setShowHistory(!showHistory)}
                            className="text-xs text-purple-600 hover:text-purple-800 flex items-center gap-1"
                        >
                            <Eye size={14} />
                            {showHistory ? 'Hide all notes' : `View all notes (${tasksWithNotes.length})`}
                        </button>
                    )}
                </div>
            </div>
        </div>
    );
};

export default DailyTracker;
